package vn.hust.restaurant.service;
import java.sql.SQLException;import java.time.*;import vn.hust.restaurant.config.AppConfig;import vn.hust.restaurant.model.UserSession;import vn.hust.restaurant.repository.AccountRepository;
public class AuthService{
 private final AccountRepository repo;private final OtpService simulated=new SimulatedOtpService(),smtp=new SmtpOtpService();private Integer resetAccountId;
 public AuthService(AccountRepository r){repo=r;}
 public UserSession login(String u,char[]pw)throws SQLException{if(u==null||u.isBlank()||pw.length==0)throw new IllegalArgumentException("Vui lòng nhập đủ tài khoản và mật khẩu");var a=repo.findByUsername(u.trim()).orElseThrow(()->new IllegalArgumentException("Sai tên đăng nhập hoặc mật khẩu"));if(!"HOAT_DONG".equals(a.accountStatus()))throw new IllegalArgumentException("Tài khoản đang bị khóa hoặc vô hiệu hóa");if(a.lockedUntil()!=null&&a.lockedUntil().isAfter(LocalDateTime.now()))throw new IllegalArgumentException("Tài khoản tạm khóa đến "+a.lockedUntil());if(!SecurityUtil.verify(new String(pw),a.passwordHash())){repo.recordFailure(a.accountId(),a.failedAttempts()+1);throw new IllegalArgumentException("Sai tên đăng nhập hoặc mật khẩu");}repo.recordSuccess(a.accountId());return repo.toSession(a);}
 public String requestOtp(String identity)throws Exception{var a=repo.findByIdentity(identity.trim()).orElseThrow(()->new IllegalArgumentException("Không tìm thấy tài khoản phù hợp"));String code=SecurityUtil.otp();repo.saveOtp(a.accountId(),code,LocalDateTime.now().plusMinutes(AppConfig.appInt("otp.expiry.minutes",5)));resetAccountId=a.accountId();String mode=AppConfig.app("otp.mode","SIMULATED");OtpService service="EMAIL".equalsIgnoreCase(mode)?smtp:simulated;String dest="EMAIL".equalsIgnoreCase(mode)?a.email():a.username();service.send(dest,code);return AppConfig.appBool("app.devMode",true)&&service instanceof SimulatedOtpService?code:service.deliveryDescription();}
 public void resetPassword(String otp,String newPassword)throws SQLException{if(resetAccountId==null)throw new IllegalStateException("Chưa yêu cầu OTP");if(newPassword==null||newPassword.length()<6)throw new IllegalArgumentException("Mật khẩu phải có ít nhất 6 ký tự");if(!repo.verifyOtp(resetAccountId,otp))throw new IllegalArgumentException("OTP sai, hết hạn hoặc đã nhập quá số lần");repo.updatePassword(resetAccountId,SecurityUtil.hash(newPassword));resetAccountId=null;}
}
